  const badId = idError(event, ctx);
  if (badId) {
    return badId;
  }
  if (state.reserved[event.id as string] !== undefined) {
    release(state, event.id as string, "cancelled");
    fillQueue(state);
  } else if (state.orders[event.id as string] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id as string), 1);
    delete state.pendingWants[event.id as string];
    state.orders[event.id as string] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

