const orig = require("./out_orig/original.js").processEvents;
const mod = require("./out_new/process_events.js").processEvents;

function shot(obj) {
  // deterministic JSON
  return JSON.stringify(obj, Object.keys(obj).sort());
}

function equal(a, b) {
  return shot(a) === shot(b);
}

function rand(seed) {
  let s = seed;
  return () => {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
}

const TYPES = ["order", "cancel", "ship", "restock", "expire"];
const ITEMS = ["a", "b", "", "c"];
let fails = 0;
let runs = 0;

for (let seed = 1; seed <= 20000; seed++) {
  const rnd = rand(seed);
  const stock = {};
  const numItems = Math.floor(rnd() * 3) + 1;
  for (let i = 0; i < numItems; i++) stock["i" + i] = Math.floor(rnd() * 10);

  const events = [];
  const ne = Math.floor(rnd() * 12);
  for (let e = 0; e < ne; e++) {
    const t = TYPES[Math.floor(rnd() * TYPES.length)];
    const ev = { type: t };
    if (rnd() < 0.8) ev.id = "o" + Math.floor(rnd() * 5);
    else if (rnd() < 0.1) ev.id = "";
    if (t === "order" || t === "restock") {
      ev.item = ITEMS[Math.floor(rnd() * ITEMS.length)] || "a";
      ev.qty = Math.floor(rnd() * 7);
    }
    if (t === "ship") {
      if (rnd() < 0.3) ev.qty = Math.floor(rnd() * 7);
    }
    events.push(ev);
  }

  const input = { stock, events };
  runs++;
  const a = orig(input);
  const b = mod(input);
  if (!equal(a, b)) {
    fails++;
    if (fails <= 5) {
      console.log("MISMATCH seed", seed);
      console.log("input", JSON.stringify(input));
      console.log("orig ", JSON.stringify(a));
      console.log("mod  ", JSON.stringify(b));
    }
  }
}

// edge/direct cases
const direct = [
  null, 5, "x", undefined,
  { stock: 3, events: [] },
  { stock: { a: -1 }, events: [] },
  { stock: { a: 1.5 }, events: [] },
  { stock: { a: 1 }, events: "no" },
  { stock: { a: 1 }, events: [null, 3] },
  { stock: { a: 1 }, events: [{ type: "bogus" }] },
  { stock: { a: 1 }, events: [{ type: "order", id: "x", item: "a", qty: 5 }] },
  { stock: { a: 10 }, events: [{ type: "order", id: "x", item: "a", qty: 5 }] },
  { stock: { a: 0 }, events: [{ type: "order", id: "x", item: "a", qty: 1 }] },
  // backorder + restock fills
  { stock: { a: 1 }, events: [
    { type: "order", id: "o1", item: "a", qty: 3 },
    { type: "order", id: "o2", item: "a", qty: 4 },
    { type: "restock", item: "a", qty: 5 },
  ]},
  // cancel releases and fills
  { stock: { a: 2 }, events: [
    { type: "order", id: "o1", item: "a", qty: 2 },
    { type: "order", id: "o2", item: "a", qty: 2 },
    { type: "cancel", id: "o1" },
  ]},
  { stock: { a: 2 }, events: [
    { type: "order", id: "o1", item: "a", qty: 2 },
    { type: "order", id: "o2", item: "a", qty: 2 },
    { type: "expire", id: "o1" },
  ]},
  // partial ship then final
  { stock: { a: 5 }, events: [
    { type: "order", id: "o1", item: "a", qty: 5 },
    { type: "ship", id: "o1", qty: 2 },
    { type: "ship", id: "o1", qty: 3 },
  ]},
];
for (const d of direct) {
  runs++;
  const a = orig(d);
  const b = mod(d);
  if (!equal(a, b)) {
    fails++;
    console.log("DIRECT MISMATCH", JSON.stringify(d));
    console.log("orig", JSON.stringify(a));
    console.log("mod ", JSON.stringify(b));
  }
}

console.log("runs", runs, "fails", fails);
process.exit(fails === 0 ? 0 : 1);

